using CorexProd.Entidad.Entidades; using CorexProd.Negocio.Negocio; using CorexProd.WPF.Helpers; using System; using System.Linq; using System.Windows;
namespace CorexProd.WPF.Modules.Tesoreria.Views { public partial class SeguroDetalleWindow:Window { readonly SeguroNegocio _seguroNegocio=new(); readonly ObligacionFinancieraNegocio _obNegocio=new(); readonly int _id; Seguro? _seguro; public SeguroDetalleWindow(int id){InitializeComponent();_id=id;Refrescar();} void Refrescar(){_seguro=_seguroNegocio.Obtener(_id);if(_seguro==null){NotificationService.Warning("No se encontró el seguro.");Close();return;}TituloTextBlock.Text=$"Seguro: {_seguro.TipoSeguro} - póliza {_seguro.NumeroPoliza}";ResumenTextBlock.Text=$"{_seguro.Obligacion.EntidadFinanciera} | {_seguro.Obligacion.Moneda} | Estado: {_seguro.Obligacion.Estado}";PeriodosGrid.ItemsSource=_seguro.Periodos;PagosGrid.ItemsSource=_seguro.Pagos;HistorialGrid.ItemsSource=_seguro.Historial;bool anul=_seguro.EstaAnulado;PagarButton.IsEnabled=!anul;AnularPeriodoButton.IsEnabled=!anul;AnularPagoButton.IsEnabled=!anul;} SeguroPeriodo? Periodo()=>PeriodosGrid.SelectedItem as SeguroPeriodo; void RegistrarPago_Click(object s,RoutedEventArgs e){var p=Periodo()??_seguro?.Periodos.FirstOrDefault(x=>x.SaldoPendiente>0&&!x.EstaAnulado);if(_seguro==null||p==null||p.SaldoPendiente<=0||p.Estado=="CANCELADA"){NotificationService.Warning("Seleccione un período pendiente o parcial con saldo.");return;}var cuota=new ObligacionFinancieraCuota{IdCuotaObligacionFinanciera=p.IdCuotaObligacionFinanciera,IdObligacionFinanciera=p.IdObligacionFinanciera,NumeroCuota=p.NumeroCuota,TotalCuotas=p.TotalCuotas,FechaVencimiento=p.FechaVencimiento,Importe=p.Importe,TotalPagado=p.TotalPagado,SaldoPendiente=p.SaldoPendiente,Estado=p.Estado};var w=new RegistrarPagoObligacionFinancieraWindow(_seguro.Obligacion,cuota){Owner=this};if(w.ShowDialog()==true)Refrescar();} void AnularPeriodo_Click(object s,RoutedEventArgs e){var p=Periodo();if(_seguro==null||p==null){NotificationService.Warning("Seleccione un período.");return;}if(p.TotalPagado>0||p.EstaAnulado){NotificationService.Warning("No se puede anular un período con pagos activos o anulado.");return;}var w=new MotivoAnulacionWindow("Anular período",p.CuotaTexto){Owner=this};if(w.ShowDialog()!=true)return;var r=_seguroNegocio.AnularPeriodo(p.IdCuotaObligacionFinanciera,SessionManager.UsuarioActual?.NombreUsuario??"Sistema",w.Motivo);if(r.Resultado){NotificationService.Success(r.Mensaje);Refrescar();}else NotificationService.Warning(r.Mensaje);} void AnularPago_Click(object s,RoutedEventArgs e){if(_seguro==null||PagosGrid.SelectedItem is not ObligacionFinancieraPago p||p.EstaAnulado){NotificationService.Warning("Seleccione un pago activo.");return;}var w=new AnularPagoObligacionFinancieraWindow($"Pago #{p.IdPago}"){Owner=this};if(w.ShowDialog()!=true)return;var r=_obNegocio.AnularPago(p.IdPago,w.MotivoAnulacion,SessionManager.UsuarioActual?.NombreUsuario??"Sistema");if(r.Resultado){NotificationService.Success(r.Mensaje);Refrescar();}else NotificationService.Warning(r.Mensaje);} } }
